+package deck
+
+import (
+	"errors"
+	"fmt"
+	"math/rand/v2"
+)
+
+// Shoe limits.
+const (
+	MinDecks           = 1
+	MaxDecks           = 8
+	CardsPerDeck       = 52
+	DefaultPenetration = 0.75
+)
+
+// Errors returned by the shoe.
+var (
+	ErrShoeEmpty    = errors.New("deck: shoe is empty")
+	ErrInvalidDecks = fmt.Errorf("deck: number of decks must be between %d and %d", MinDecks, MaxDecks)
+	ErrInvalidPen   = errors.New("deck: penetration must be in (0, 1]")
+)
+
+// Shoe is a dealing shoe containing one or more shuffled 52-card decks with a
+// cut card placed at a configurable penetration depth.
+type Shoe struct {
+	cards    []Card
+	pos      int
+	numDecks int
+	cutIndex int
+	rng      *rand.Rand
+}
+
+// NewShoe builds a shoe of numDecks standard decks (1–8), shuffles it, and
+// places the cut card at len(cards)*penetration. A penetration of 0 selects
+// DefaultPenetration. If rng is nil a randomly seeded generator is used.
+func NewShoe(numDecks int, penetration float64, rng *rand.Rand) (*Shoe, error) {
+	if numDecks < MinDecks || numDecks > MaxDecks {
+		return nil, ErrInvalidDecks
+	}
+	if penetration == 0 {
+		penetration = DefaultPenetration
+	}
+	if penetration < 0 || penetration > 1 {
+		return nil, ErrInvalidPen
+	}
+	if rng == nil {
+		rng = rand.New(rand.NewPCG(rand.Uint64(), rand.Uint64()))
+	}
+	cards := make([]Card, 0, numDecks*CardsPerDeck)
+	for d := 0; d < numDecks; d++ {
+		for _, s := range Suits {
+			for _, r := range Ranks {
+				cards = append(cards, Card{Suit: s, Rank: r})
+			}
+		}
+	}
+	s := &Shoe{
+		cards:    cards,
+		numDecks: numDecks,
+		cutIndex: int(float64(len(cards)) * penetration),
+		rng:      rng,
+	}
+	if s.cutIndex < 1 {
+		s.cutIndex = 1
+	}
+	s.Shuffle()
+	return s, nil
+}
+
+// NewShoeFromCards builds an unshuffled shoe that deals the given cards in
+// order. It is intended for deterministic tests and scripted scenarios. The cut
+// card is placed at the very end so NeedsShuffle only becomes true when the
+// cards are exhausted.
+func NewShoeFromCards(cards []Card) *Shoe {
+	cp := make([]Card, len(cards))
+	copy(cp, cards)
+	return &Shoe{
+		cards:    cp,
+		numDecks: (len(cp) + CardsPerDeck - 1) / CardsPerDeck,
+		cutIndex: len(cp),
+		rng:      rand.New(rand.NewPCG(0, 0)),
+	}
+}
+
+// Shuffle performs an in-place Fisher-Yates shuffle over the entire shoe and
+// resets the dealing position to the top.
+func (s *Shoe) Shuffle() {
+	for i := len(s.cards) - 1; i > 0; i-- {
+		j := s.rng.IntN(i + 1)
+		s.cards[i], s.cards[j] = s.cards[j], s.cards[i]
+	}
+	s.pos = 0
+}
+
+// Draw deals the next card. It returns ErrShoeEmpty when no cards remain.
+func (s *Shoe) Draw() (Card, error) {
+	if s.pos >= len(s.cards) {
+		return Card{}, ErrShoeEmpty
+	}
+	c := s.cards[s.pos]
+	s.pos++
+	return c, nil
+}
+
+// NeedsShuffle reports whether the cut card has been reached.
+func (s *Shoe) NeedsShuffle() bool {
+	return s.pos >= s.cutIndex
+}
+
+// Remaining returns the number of undealt cards.
+func (s *Shoe) Remaining() int {
+	return len(s.cards) - s.pos
+}
+
+// Size returns the total number of cards in the shoe.
+func (s *Shoe) Size() int {
+	return len(s.cards)
+}
+
+// NumDecks returns the number of decks in the shoe.
+func (s *Shoe) NumDecks() int {
+	return s.numDecks
+}
+
+// CutIndex returns the position of the cut card.
+func (s *Shoe) CutIndex() int {
+	return s.cutIndex
+}

