+package deck
+
+import (
+	"errors"
+	"math/rand/v2"
+	"testing"
+)
+
+func TestCardValue(t *testing.T) {
+	tests := []struct {
+		rank Rank
+		want int
+	}{
+		{Ace, 11}, {Two, 2}, {Three, 3}, {Four, 4}, {Five, 5}, {Six, 6},
+		{Seven, 7}, {Eight, 8}, {Nine, 9}, {Ten, 10}, {Jack, 10}, {Queen, 10}, {King, 10},
+	}
+	for _, tt := range tests {
+		c := Card{Suit: Spades, Rank: tt.rank}
+		if got := c.Value(); got != tt.want {
+			t.Errorf("Card{%v}.Value() = %d, want %d", tt.rank, got, tt.want)
+		}
+	}
+	if !(Card{Rank: Ace}).IsAce() {
+		t.Error("Ace should report IsAce")
+	}
+	if (Card{Rank: King}).IsAce() {
+		t.Error("King should not report IsAce")
+	}
+}
+
+func TestStrings(t *testing.T) {
+	tests := []struct {
+		card Card
+		want string
+	}{
+		{Card{Hearts, Ace}, "A♥"},
+		{Card{Spades, Ten}, "10♠"},
+		{Card{Diamonds, King}, "K♦"},
+		{Card{Clubs, Queen}, "Q♣"},
+		{Card{Clubs, Jack}, "J♣"},
+		{Card{Spades, Two}, "2♠"},
+	}
+	for _, tt := range tests {
+		if got := tt.card.String(); got != tt.want {
+			t.Errorf("%+v.String() = %q, want %q", tt.card, got, tt.want)
+		}
+	}
+	if Suit(99).String() != "?" || Rank(99).String() != "?" {
+		t.Error("unknown suit/rank should render as ?")
+	}
+	if !Hearts.IsRed() || !Diamonds.IsRed() || Spades.IsRed() || Clubs.IsRed() {
+		t.Error("IsRed mismatch")
+	}
+}
+
+func TestNewShoeSizes(t *testing.T) {
+	for n := MinDecks; n <= MaxDecks; n++ {
+		s, err := NewShoe(n, 0, rand.New(rand.NewPCG(1, 2)))
+		if err != nil {
+			t.Fatalf("NewShoe(%d) error: %v", n, err)
+		}
+		if s.Size() != n*CardsPerDeck {
+			t.Errorf("NewShoe(%d).Size() = %d, want %d", n, s.Size(), n*CardsPerDeck)
+		}
+		if s.NumDecks() != n {
+			t.Errorf("NumDecks = %d, want %d", s.NumDecks(), n)
+		}
+		if s.Remaining() != s.Size() {
+			t.Errorf("fresh shoe Remaining = %d, want %d", s.Remaining(), s.Size())
+		}
+		wantCut := int(float64(s.Size()) * DefaultPenetration)
+		if s.CutIndex() != wantCut {
+			t.Errorf("CutIndex = %d, want %d", s.CutIndex(), wantCut)
+		}
+	}
+}
+
+func TestNewShoeInvalid(t *testing.T) {
+	if _, err := NewShoe(0, 0, nil); !errors.Is(err, ErrInvalidDecks) {
+		t.Errorf("NewShoe(0) err = %v, want ErrInvalidDecks", err)
+	}
+	if _, err := NewShoe(9, 0, nil); !errors.Is(err, ErrInvalidDecks) {
+		t.Errorf("NewShoe(9) err = %v, want ErrInvalidDecks", err)
+	}
+	if _, err := NewShoe(1, 1.5, nil); !errors.Is(err, ErrInvalidPen) {
+		t.Errorf("NewShoe pen 1.5 err = %v, want ErrInvalidPen", err)
+	}
+	if _, err := NewShoe(1, -0.1, nil); !errors.Is(err, ErrInvalidPen) {
+		t.Errorf("NewShoe pen -0.1 err = %v, want ErrInvalidPen", err)
+	}
+}
+
+func TestNewShoeNilRNG(t *testing.T) {
+	s, err := NewShoe(1, 0.5, nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.Size() != 52 {
+		t.Errorf("size = %d", s.Size())
+	}
+}
+
+func TestShoeCompositionPreserved(t *testing.T) {
+	const decks = 6
+	s, err := NewShoe(decks, 0, rand.New(rand.NewPCG(7, 7)))
+	if err != nil {
+		t.Fatal(err)
+	}
+	counts := map[Card]int{}
+	for {
+		c, err := s.Draw()
+		if err != nil {
+			break
+		}
+		counts[c]++
+	}
+	if len(counts) != 52 {
+		t.Fatalf("distinct cards = %d, want 52", len(counts))
+	}
+	for c, n := range counts {
+		if n != decks {
+			t.Errorf("card %v appears %d times, want %d", c, n, decks)
+		}
+	}
+}
+
+func TestShuffleDeterministicWithSeed(t *testing.T) {
+	a, _ := NewShoe(2, 0, rand.New(rand.NewPCG(42, 42)))
+	b, _ := NewShoe(2, 0, rand.New(rand.NewPCG(42, 42)))
+	for i := 0; i < a.Size(); i++ {
+		ca, _ := a.Draw()
+		cb, _ := b.Draw()
+		if ca != cb {
+			t.Fatalf("seeded shoes diverge at index %d: %v vs %v", i, ca, cb)
+		}
+	}
+}
+
+func TestShuffleChangesOrder(t *testing.T) {
+	s, _ := NewShoe(1, 0, rand.New(rand.NewPCG(1, 1)))
+	first := make([]Card, s.Size())
+	for i := range first {
+		first[i], _ = s.Draw()
+	}
+	s.Shuffle()
+	if s.Remaining() != s.Size() {
+		t.Fatalf("Shuffle should reset position; remaining = %d", s.Remaining())
+	}
+	same := 0
+	for i := range first {
+		c, _ := s.Draw()
+		if c == first[i] {
+			same++
+		}
+	}
+	if same == len(first) {
+		t.Error("shuffle produced identical ordering")
+	}
+}
+
+func TestDrawEmpty(t *testing.T) {
+	s := NewShoeFromCards([]Card{{Spades, Ace}})
+	c, err := s.Draw()
+	if err != nil || c != (Card{Spades, Ace}) {
+		t.Fatalf("Draw = %v, %v", c, err)
+	}
+	if _, err := s.Draw(); !errors.Is(err, ErrShoeEmpty) {
+		t.Errorf("Draw on empty shoe err = %v, want ErrShoeEmpty", err)
+	}
+	if s.Remaining() != 0 {
+		t.Errorf("Remaining = %d, want 0", s.Remaining())
+	}
+}
+
+func TestCutCardPenetration(t *testing.T) {
+	s, err := NewShoe(1, 0.5, rand.New(rand.NewPCG(3, 3)))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.NeedsShuffle() {
+		t.Fatal("fresh shoe should not need shuffle")
+	}
+	for i := 0; i < 25; i++ {
+		s.Draw()
+	}
+	if s.NeedsShuffle() {
+		t.Error("should not need shuffle before cut card (25 of 26)")
+	}
+	s.Draw()
+	if !s.NeedsShuffle() {
+		t.Error("should need shuffle at cut card (26 of 52)")
+	}
+	s.Shuffle()
+	if s.NeedsShuffle() {
+		t.Error("after reshuffle should not need shuffle")
+	}
+}
+
+func TestCutIndexMinimumOne(t *testing.T) {
+	s, err := NewShoe(1, 0.001, rand.New(rand.NewPCG(3, 3)))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.CutIndex() != 1 {
+		t.Errorf("CutIndex = %d, want 1", s.CutIndex())
+	}
+}
+
+func TestNewShoeFromCardsOrder(t *testing.T) {
+	cards := []Card{{Hearts, Ace}, {Spades, King}, {Clubs, Five}}
+	s := NewShoeFromCards(cards)
+	// mutate original to ensure the shoe copied it
+	cards[0] = Card{Clubs, Two}
+	if s.NumDecks() != 1 {
+		t.Errorf("NumDecks = %d, want 1", s.NumDecks())
+	}
+	want := []Card{{Hearts, Ace}, {Spades, King}, {Clubs, Five}}
+	for i, w := range want {
+		c, err := s.Draw()
+		if err != nil {
+			t.Fatal(err)
+		}
+		if c != w {
+			t.Errorf("card %d = %v, want %v", i, c, w)
+		}
+	}
+	if !s.NeedsShuffle() {
+		t.Error("scripted shoe should need shuffle when exhausted")
+	}
+}

