+package game
+
+import (
+	"fmt"
+
+	"blackjack/internal/deck"
+)
+
+// Hand is a set of cards held by the player or dealer together with the
+// wager riding on it and its lifecycle flags.
+type Hand struct {
+	Cards     []deck.Card
+	Bet       int
+	Doubled   bool
+	FromSplit bool
+	// Done is set once the hand can take no further action (stood, busted,
+	// doubled, or reached 21).
+	Done bool
+}
+
+// NewHand creates a hand with the given wager and starting cards.
+func NewHand(bet int, cards ...deck.Card) *Hand {
+	h := &Hand{Bet: bet}
+	for _, c := range cards {
+		h.Add(c)
+	}
+	return h
+}
+
+// Add appends a card to the hand.
+func (h *Hand) Add(c deck.Card) {
+	h.Cards = append(h.Cards, c)
+}
+
+// Total evaluates the hand with dynamic aces. Every ace starts at 11 and is
+// demoted to 1 while the total exceeds 21. soft reports whether an ace is
+// still being counted as 11.
+func (h Hand) Total() (total int, soft bool) {
+	aces := 0
+	for _, c := range h.Cards {
+		total += c.Value()
+		if c.IsAce() {
+			aces++
+		}
+	}
+	for total > 21 && aces > 0 {
+		total -= 10
+		aces--
+	}
+	return total, aces > 0
+}
+
+// Value returns only the numeric total.
+func (h Hand) Value() int {
+	t, _ := h.Total()
+	return t
+}
+
+// IsSoft reports whether the hand contains an ace counted as 11.
+func (h Hand) IsSoft() bool {
+	_, soft := h.Total()
+	return soft
+}
+
+// IsBust reports whether the total exceeds 21.
+func (h Hand) IsBust() bool {
+	return h.Value() > 21
+}
+
+// IsBlackjack reports a natural: exactly two cards totalling 21 on a hand
+// that was not produced by a split.
+func (h Hand) IsBlackjack() bool {
+	return len(h.Cards) == 2 && !h.FromSplit && h.Value() == 21
+}
+
+// IsPair reports whether the hand is exactly two cards of equal blackjack
+// value (so 10/J/Q/K pair with each other).
+func (h Hand) IsPair() bool {
+	return len(h.Cards) == 2 && h.Cards[0].Value() == h.Cards[1].Value()
+}
+
+// CanDouble reports whether doubling is permitted under the rules.
+func (h Hand) CanDouble(r Rules) bool {
+	if len(h.Cards) != 2 || h.Done || h.Doubled {
+		return false
+	}
+	if h.FromSplit && !r.DoubleAfterSplit {
+		return false
+	}
+	return true
+}
+
+// CanSplit reports whether this hand may be split given the number of hands
+// the player currently holds.
+func (h Hand) CanSplit(r Rules, numHands int) bool {
+	return h.IsPair() && !h.Done && numHands < r.MaxSplitHands
+}
+
+// Describe returns a short textual description, e.g. "Soft 17", "Hard 20",
+// "Blackjack" or "Bust".
+func (h Hand) Describe() string {
+	if len(h.Cards) == 0 {
+		return "Empty"
+	}
+	if h.IsBlackjack() {
+		return "Blackjack"
+	}
+	total, soft := h.Total()
+	if total > 21 {
+		return fmt.Sprintf("Bust (%d)", total)
+	}
+	if soft {
+		return fmt.Sprintf("Soft %d", total)
+	}
+	return fmt.Sprintf("Hard %d", total)
+}
+
+// String lists the cards, e.g. "10♠ A♥".
+func (h Hand) String() string {
+	s := ""
+	for i, c := range h.Cards {
+		if i > 0 {
+			s += " "
+		}
+		s += c.String()
+	}
+	return s
+}

