+package game
+
+import (
+	"errors"
+	"fmt"
+
+	"blackjack/internal/deck"
+)
+
+// Errors returned by the round state machine.
+var (
+	ErrNoActiveHand  = errors.New("game: no active player hand")
+	ErrInvalidAction = errors.New("game: action not permitted for this hand")
+	ErrDealerPlayed  = errors.New("game: dealer has already played")
+	ErrDealerPending = errors.New("game: dealer has not played yet")
+)
+
+// Result is the settled outcome of one player hand.
+type Result struct {
+	Hand    *Hand
+	Outcome Outcome
+	// Net is the player's profit (positive) or loss (negative) on the hand.
+	Net int
+}
+
+// Round is a single blackjack round for one player seat against the dealer.
+type Round struct {
+	Rules  Rules
+	Shoe   *deck.Shoe
+	Dealer *Hand
+	Hands  []*Hand
+	// Active indexes the hand awaiting a decision, or -1 once the player
+	// phase is complete.
+	Active int
+
+	dealerPlayed bool
+}
+
+// NewRound validates the bet, deals the opening cards (player, dealer,
+// player, dealer) and resolves naturals. If the shoe runs out mid-deal it is
+// reshuffled transparently.
+func NewRound(shoe *deck.Shoe, rules Rules, bet int) (*Round, error) {
+	if shoe == nil {
+		return nil, errors.New("game: shoe is nil")
+	}
+	if bet < rules.MinBet || bet > rules.MaxBet {
+		return nil, fmt.Errorf("game: bet $%d outside allowed range $%d–$%d", bet, rules.MinBet, rules.MaxBet)
+	}
+	r := &Round{
+		Rules:  rules,
+		Shoe:   shoe,
+		Dealer: &Hand{},
+		Active: 0,
+	}
+	player := &Hand{Bet: bet}
+	r.Hands = []*Hand{player}
+
+	player.Add(r.draw())
+	r.Dealer.Add(r.draw())
+	player.Add(r.draw())
+	r.Dealer.Add(r.draw())
+
+	// Player natural ends the player's turn immediately; dealer peek for a
+	// natural also ends the round before any further wagering.
+	if player.IsBlackjack() || r.Dealer.IsBlackjack() {
+		player.Done = true
+	}
+	r.advance()
+	return r, nil
+}
+
+// draw takes the next card, reshuffling if the shoe is exhausted.
+func (r *Round) draw() deck.Card {
+	c, err := r.Shoe.Draw()
+	if err != nil {
+		r.Shoe.Shuffle()
+		c, _ = r.Shoe.Draw()
+	}
+	return c
+}
+
+// advance moves Active to the next hand that still needs a decision.
+func (r *Round) advance() {
+	if r.Active < 0 {
+		return
+	}
+	for r.Active < len(r.Hands) && r.Hands[r.Active].Done {
+		r.Active++
+	}
+	if r.Active >= len(r.Hands) {
+		r.Active = -1
+	}
+}
+
+// CurrentHand returns the hand awaiting a decision, or nil if none.
+func (r *Round) CurrentHand() *Hand {
+	if r.Active < 0 || r.Active >= len(r.Hands) {
+		return nil
+	}
+	return r.Hands[r.Active]
+}
+
+// PlayerTurnOver reports whether every player hand is finished.
+func (r *Round) PlayerTurnOver() bool {
+	return r.Active < 0
+}
+
+// DealerUpcard returns the dealer's visible card.
+func (r *Round) DealerUpcard() deck.Card {
+	return r.Dealer.Cards[0]
+}
+
+// DealerPlayed reports whether the dealer has completed their draw.
+func (r *Round) DealerPlayed() bool {
+	return r.dealerPlayed
+}
+
+// AvailableActions lists the legal actions for the current hand.
+func (r *Round) AvailableActions() []Action {
+	h := r.CurrentHand()
+	if h == nil {
+		return nil
+	}
+	acts := []Action{Hit, Stand}
+	if h.CanDouble(r.Rules) {
+		acts = append(acts, Double)
+	}
+	if h.CanSplit(r.Rules, len(r.Hands)) {
+		acts = append(acts, Split)
+	}
+	return acts
+}
+
+// Apply performs the given action on the current hand and advances the turn.
+func (r *Round) Apply(a Action) error {
+	h := r.CurrentHand()
+	if h == nil {
+		return ErrNoActiveHand
+	}
+	switch a {
+	case Hit:
+		h.Add(r.draw())
+		if h.Value() >= 21 {
+			h.Done = true
+		}
+	case Stand:
+		h.Done = true
+	case Double:
+		if !h.CanDouble(r.Rules) {
+			return ErrInvalidAction
+		}
+		h.Bet *= 2
+		h.Doubled = true
+		h.Add(r.draw())
+		h.Done = true
+	case Split:
+		if !h.CanSplit(r.Rules, len(r.Hands)) {
+			return ErrInvalidAction
+		}
+		second := &Hand{Bet: h.Bet, FromSplit: true}
+		second.Add(h.Cards[1])
+		h.Cards = h.Cards[:1]
+		h.FromSplit = true
+
+		h.Add(r.draw())
+		second.Add(r.draw())
+
+		// Insert the new hand immediately after the current one.
+		idx := r.Active + 1
+		r.Hands = append(r.Hands, nil)
+		copy(r.Hands[idx+1:], r.Hands[idx:])
+		r.Hands[idx] = second
+
+		// Split aces receive one card each and stand automatically.
+		if h.Cards[0].IsAce() {
+			h.Done = true
+			second.Done = true
+		} else {
+			if h.Value() >= 21 {
+				h.Done = true
+			}
+			if second.Value() >= 21 {
+				second.Done = true
+			}
+		}
+	default:
+		return ErrInvalidAction
+	}
+	r.advance()
+	return nil
+}
+
+// PlayDealer completes the dealer's hand. The dealer only draws when at least
+// one player hand is still live (not bust and not a natural). Under S17 the
+// dealer stands on all 17s; under H17 the dealer hits soft 17.
+func (r *Round) PlayDealer() error {
+	if !r.PlayerTurnOver() {
+		return ErrNoActiveHand
+	}
+	if r.dealerPlayed {
+		return ErrDealerPlayed
+	}
+	r.dealerPlayed = true
+	if !r.anyLiveHand() || r.Dealer.IsBlackjack() {
+		return nil
+	}
+	for {
+		total, soft := r.Dealer.Total()
+		if total < 17 {
+			r.Dealer.Add(r.draw())
+			continue
+		}
+		if total == 17 && soft && r.Rules.DealerHitsSoft17 {
+			r.Dealer.Add(r.draw())
+			continue
+		}
+		return nil
+	}
+}
+
+// anyLiveHand reports whether any player hand still needs to be compared
+// against the dealer's final total.
+func (r *Round) anyLiveHand() bool {
+	for _, h := range r.Hands {
+		if !h.IsBust() && !h.IsBlackjack() {
+			return true
+		}
+	}
+	return false
+}
+
+// Settle computes the outcome and net payout for every player hand. It must
+// be called after PlayDealer.
+func (r *Round) Settle() ([]Result, error) {
+	if !r.dealerPlayed {
+		return nil, ErrDealerPending
+	}
+	results := make([]Result, 0, len(r.Hands))
+	dealerBJ := r.Dealer.IsBlackjack()
+	dealerTotal := r.Dealer.Value()
+	dealerBust := dealerTotal > 21
+
+	for _, h := range r.Hands {
+		res := Result{Hand: h}
+		playerTotal := h.Value()
+		switch {
+		case h.IsBlackjack() && dealerBJ:
+			res.Outcome, res.Net = Push, 0
+		case h.IsBlackjack():
+			res.Outcome, res.Net = Blackjack, r.Rules.BlackjackWinnings(h.Bet)
+		case h.IsBust():
+			res.Outcome, res.Net = Loss, -h.Bet
+		case dealerBJ:
+			res.Outcome, res.Net = Loss, -h.Bet
+		case dealerBust:
+			res.Outcome, res.Net = Win, h.Bet
+		case playerTotal > dealerTotal:
+			res.Outcome, res.Net = Win, h.Bet
+		case playerTotal < dealerTotal:
+			res.Outcome, res.Net = Loss, -h.Bet
+		default:
+			res.Outcome, res.Net = Push, 0
+		}
+		results = append(results, res)
+	}
+	return results, nil
+}
+
+// TotalWagered returns the sum of all bets on the table (after doubles/splits).
+func (r *Round) TotalWagered() int {
+	sum := 0
+	for _, h := range r.Hands {
+		sum += h.Bet
+	}
+	return sum
+}

