+func hand(ranks ...deck.Rank) Hand {
+	h := Hand{}
+	for _, r := range ranks {
+		h.Add(c(r))
+	}
+	return h
+}
+
+// scripted builds a round from an explicit dealing order:
+// player1, dealer1, player2, dealer2, then subsequent draws.
+func scripted(t *testing.T, bet int, ranks ...deck.Rank) *Round {
+	t.Helper()
+	cards := make([]deck.Card, len(ranks))
+	for i, r := range ranks {
+		cards[i] = c(r)
+	}
+	r, err := NewRound(deck.NewShoeFromCards(cards), DefaultRules(), bet)
+	if err != nil {
+		t.Fatalf("NewRound: %v", err)
+	}
+	return r
+}
