+func TestSplitThenSecondHandHits21(t *testing.T) {
+	// 9+9 split: hand1 gets 2 (11), hand2 gets Q (19); hand1 hits K -> 21 auto-done.
+	r := scripted(t, 10, deck.Nine, deck.Five, deck.Nine, deck.Ten, deck.Two, deck.Queen, deck.King, deck.Two)
+	_ = r.Apply(Split)
+	_ = r.Apply(Hit)
+	if r.Hands[0].Value() != 21 || !r.Hands[0].Done {
+		t.Error("hand1 should be 21 and done")
+	}
+	if r.CurrentHand() != r.Hands[1] {
+		t.Error("hand2 should be active")
+	}
+}
+
+func TestSplitAutoDoneOn21AfterSplit(t *testing.T) {
+	// 10+10 split: hand1 gets A (21 done), hand2 gets A (21 done).
+	r := scripted(t, 10, deck.Ten, deck.Five, deck.King, deck.Ten, deck.Ace, deck.Ace, deck.Two)
+	_ = r.Apply(Split)
+	if !r.PlayerTurnOver() {
+		t.Error("both split hands at 21 should finish the turn")
+	}
+}
+
+func TestSplitNotAllowedOnNonPair(t *testing.T) {
+	r := scripted(t, 10, deck.Eight, deck.Ten, deck.Nine, deck.Seven)
+	if err := r.Apply(Split); !errors.Is(err, ErrInvalidAction) {
+		t.Errorf("err = %v", err)
+	}
+}
+
+func TestErrorsAndOrdering(t *testing.T) {
+	r := scripted(t, 10, deck.Ten, deck.Ten, deck.Eight, deck.Eight)
+	if err := r.Apply(Action(42)); !errors.Is(err, ErrInvalidAction) {
+		t.Errorf("unknown action err = %v", err)
+	}
+	if err := r.PlayDealer(); !errors.Is(err, ErrNoActiveHand) {
+		t.Errorf("PlayDealer before turn over err = %v", err)
+	}
+	if _, err := r.Settle(); !errors.Is(err, ErrDealerPending) {
+		t.Errorf("Settle before dealer err = %v", err)
+	}
+	_ = r.Apply(Stand)
+	if err := r.Apply(Hit); !errors.Is(err, ErrNoActiveHand) {
+		t.Errorf("Apply after turn over err = %v", err)
+	}
+	if r.AvailableActions() != nil {
+		t.Error("no actions when no active hand")
+	}
+	if err := r.PlayDealer(); err != nil {
+		t.Fatal(err)
+	}
+	if !r.DealerPlayed() {
+		t.Error("DealerPlayed should be true")
+	}
+	if err := r.PlayDealer(); !errors.Is(err, ErrDealerPlayed) {
+		t.Errorf("second PlayDealer err = %v", err)
+	}
+}
+
+func TestDrawReshufflesWhenShoeExhausted(t *testing.T) {
+	// Only 4 cards; player hits forcing a reshuffle of the scripted shoe.
+	r := scripted(t, 10, deck.Two, deck.Ten, deck.Three, deck.Seven)
+	if err := r.Apply(Hit); err != nil {
+		t.Fatal(err)
+	}
+	if len(r.Hands[0].Cards) != 3 {
+		t.Error("hit should still deliver a card after reshuffle")
+	}
+}

