+// Package strategy implements table-driven Basic Strategy for multi-deck
+// blackjack with the dealer standing on soft 17 and double after split.
+package strategy
+
+import (
+	"fmt"
+
+	"blackjack/internal/deck"
+	"blackjack/internal/game"
+)
+
+// Options tells Recommend which actions are currently legal so it can fall
+// back correctly (e.g. a 3-card hard 11 cannot double, so it hits).
+type Options struct {
+	CanDouble bool
+	CanSplit  bool
+}
+
+// Recommend returns the Basic Strategy action for the hand against the
+// dealer's upcard, honoring the legality constraints in opts.
+func Recommend(h game.Hand, dealerUp deck.Card, opts Options) game.Action {
+	col := column(dealerUp)
+	total, soft := h.Total()
+
+	if total >= 21 {
+		return game.Stand
+	}
+
+	if opts.CanSplit && h.IsPair() {
+		cell := lookup(pairTable, h.Cards[0].Value(), col)
+		if cell == cSplit {
+			return game.Split
+		}
+		return resolve(cell, opts.CanDouble)
+	}
+
+	if soft {
+		return resolve(lookup(softTable, total, col), opts.CanDouble)
+	}
+	if total < 5 {
+		return game.Hit
+	}
+	return resolve(lookup(hardTable, total, col), opts.CanDouble)
+}
+
+// Explain returns a human readable justification alongside the recommendation,
+// e.g. "Pair of 8s vs dealer 10 → Split".
+func Explain(h game.Hand, dealerUp deck.Card, opts Options) string {
+	act := Recommend(h, dealerUp, opts)
+	total, soft := h.Total()
+	var desc string
+	switch {
+	case opts.CanSplit && h.IsPair() && act == game.Split:
+		desc = fmt.Sprintf("Pair of %ss", h.Cards[0].Rank)
+	case soft:
+		desc = fmt.Sprintf("Soft %d", total)
+	default:
+		desc = fmt.Sprintf("Hard %d", total)
+	}
+	return fmt.Sprintf("%s vs dealer %s → %s", desc, dealerUp.Rank, act)
+}
+
+// column maps a dealer upcard to its table column (2..9 → 0..7, ten-value → 8, Ace → 9).
+func column(c deck.Card) int {
+	return c.Value() - 2
+}
+
+// lookup returns the cell for the given row key and column, defaulting to
+// Stand for totals above the table range and Hit below it.
+func lookup(table map[int]string, key, col int) rune {
+	row, ok := table[key]
+	if !ok {
+		if key > 21 {
+			return cStand
+		}
+		return cHit
+	}
+	if col < 0 || col >= numCols {
+		return cStand
+	}
+	return rune(row[col])
+}
+
+// resolve converts a table cell to an action, applying fallbacks when
+// doubling is not permitted.
+func resolve(cell rune, canDouble bool) game.Action {
+	switch cell {
+	case cHit:
+		return game.Hit
+	case cStand:
+		return game.Stand
+	case cDoubleHit:
+		if canDouble {
+			return game.Double
+		}
+		return game.Hit
+	case cDoubleStand:
+		if canDouble {
+			return game.Double
+		}
+		return game.Stand
+	case cSplit:
+		return game.Split
+	default:
+		return game.Stand
+	}
+}

