// Package ui renders cards, hands and table status for the terminal using
// compact ANSI-styled output.
package ui

import (
	"fmt"
	"io"
	"strings"

	"blackjack/internal/deck"
	"blackjack/internal/game"
)

// ANSI escape sequences.
const (
	ansiReset = "\x1b[0m"
	ansiRed   = "\x1b[31m"
	ansiBold  = "\x1b[1m"
	ansiDim   = "\x1b[2m"
	ansiGreen = "\x1b[32m"
	ansiCyan  = "\x1b[36m"
)

// Renderer renders game state. Color controls whether ANSI escapes are
// emitted; disable it for plain-text output or tests.
type Renderer struct {
	Color bool
}

// New returns a Renderer with color enabled or disabled.
func New(color bool) *Renderer {
	return &Renderer{Color: color}
}

func (r *Renderer) wrap(code, s string) string {
	if !r.Color {
		return s
	}
	return code + s + ansiReset
}

// Card renders a single card as a fixed-width token such as "[ 10♠ ]" or
// "[  A♥ ]". Hearts and diamonds are colored red when Color is enabled.
func (r *Renderer) Card(c deck.Card) string {
	label := fmt.Sprintf("%3s", c.String()) // pad to width 3 (rune-aware via Sprintf on runes)
	// Sprintf pads by bytes, not runes; the suit symbol is multi-byte so pad manually.
	label = padLeft(c.String(), 3)
	if c.Suit.IsRed() {
		label = r.wrap(ansiRed, label)
	}
	return "[ " + label + " ]"
}

// Hidden renders a face-down card.
func (r *Renderer) Hidden() string {
	return "[ " + r.wrap(ansiDim, "??") + " ]"
}

// Hand renders every card in the hand followed by its description, e.g.
// "[ 10♠ ] [  A♥ ] (Soft 21)". When hideHole is set the second card is
// rendered face-down and no total is shown.
func (r *Renderer) Hand(h game.Hand, hideHole bool) string {
	var sb strings.Builder
	for i, c := range h.Cards {
		if i > 0 {
			sb.WriteByte(' ')
		}
		if hideHole && i == 1 {
			sb.WriteString(r.Hidden())
			continue
		}
		sb.WriteString(r.Card(c))
	}
	if hideHole {
		return sb.String()
	}
	sb.WriteString(" (")
	sb.WriteString(h.Describe())
	sb.WriteByte(')')
	return sb.String()
}

// Money formats a dollar amount with thousands separators, e.g. "$1,000" or "-$250".
func Money(n int) string {
	neg := n < 0
	if neg {
		n = -n
	}
	digits := fmt.Sprintf("%d", n)
	var sb strings.Builder
	for i, d := range digits {
		if i > 0 && (len(digits)-i)%3 == 0 {
			sb.WriteByte(',')
		}
		sb.WriteRune(d)
	}
	if neg {
		return "-$" + sb.String()
	}
	return "$" + sb.String()
}

// SignedMoney formats a profit/loss with an explicit sign, e.g. "+$15" or "-$10".
func SignedMoney(n int) string {
	if n > 0 {
		return "+" + Money(n)
	}
	return Money(n)
}

// Table writes the current table status: bankroll, bet, dealer hand (with hole
// card hidden until the dealer has played) and every player hand, marking the
// active one.
func (r *Renderer) Table(w io.Writer, bankroll int, rd *game.Round) {
	hideHole := !rd.DealerPlayed()
	fmt.Fprintln(w, r.wrap(ansiBold, "────────────────────────────────────────"))
	fmt.Fprintf(w, "Bankroll: %s   Bet: %s   Dealer upcard: %s\n",
		r.wrap(ansiGreen, Money(bankroll)),
		r.wrap(ansiCyan, Money(rd.TotalWagered())),
		rd.DealerUpcard())
	fmt.Fprintf(w, "Dealer: %s\n", r.Hand(*rd.Dealer, hideHole))
	for i, h := range rd.Hands {
		marker := "  "
		if i == rd.Active {
			marker = r.wrap(ansiBold, "► ")
		}
		label := "Player"
		if len(rd.Hands) > 1 {
			label = fmt.Sprintf("Hand %d", i+1)
		}
		fmt.Fprintf(w, "%s%s: %s  [%s]\n", marker, label, r.Hand(*h, false), Money(h.Bet))
	}
	fmt.Fprintln(w, r.wrap(ansiBold, "────────────────────────────────────────"))
}

// Results writes the settled outcome of each hand.
func (r *Renderer) Results(w io.Writer, results []game.Result) {
	for i, res := range results {
		label := "Result"
		if len(results) > 1 {
			label = fmt.Sprintf("Hand %d", i+1)
		}
		color := ansiDim
		switch res.Outcome {
		case game.Win, game.Blackjack:
			color = ansiGreen
		case game.Loss:
			color = ansiRed
		}
		fmt.Fprintf(w, "%s: %s (%s)\n", label, r.wrap(color, res.Outcome.String()), SignedMoney(res.Net))
	}
}

// padLeft pads s with spaces on the left to the given rune width.
func padLeft(s string, width int) string {
	n := len([]rune(s))
	if n >= width {
		return s
	}
	return strings.Repeat(" ", width-n) + s
}

