@@ -0,0 +1,174 @@
+package ui
+
+import (
+	"bytes"
+	"strings"
+	"testing"
+
+	"blackjack/internal/deck"
+	"blackjack/internal/game"
+)
+
+func card(s deck.Suit, r deck.Rank) deck.Card { return deck.Card{Suit: s, Rank: r} }
+
+func TestCardRendering(t *testing.T) {
+	r := New(false)
+	tests := []struct {
+		c    deck.Card
+		want string
+	}{
+		{card(deck.Spades, deck.Ten), "[ 10♠ ]"},
+		{card(deck.Hearts, deck.Ace), "[  A♥ ]"},
+		{card(deck.Diamonds, deck.King), "[  K♦ ]"},
+		{card(deck.Clubs, deck.Two), "[  2♣ ]"},
+	}
+	for _, tt := range tests {
+		if got := r.Card(tt.c); got != tt.want {
+			t.Errorf("Card(%v) = %q, want %q", tt.c, got, tt.want)
+		}
+	}
+}
+
+func TestCardColor(t *testing.T) {
+	r := New(true)
+	red := r.Card(card(deck.Hearts, deck.Ace))
+	if !strings.Contains(red, ansiRed) || !strings.Contains(red, ansiReset) {
+		t.Errorf("red suit should be colored: %q", red)
+	}
+	black := r.Card(card(deck.Spades, deck.Ace))
+	if strings.Contains(black, ansiRed) {
+		t.Errorf("black suit should not be red: %q", black)
+	}
+	if !strings.Contains(r.Hidden(), ansiDim) {
+		t.Error("hidden card should be dim when colored")
+	}
+	if New(false).Hidden() != "[ ?? ]" {
+		t.Errorf("Hidden() = %q", New(false).Hidden())
+	}
+}
+
+func TestHandRendering(t *testing.T) {
+	r := New(false)
+	h := game.Hand{}
+	h.Add(card(deck.Spades, deck.Ten))
+	h.Add(card(deck.Hearts, deck.Ace))
+	if got := r.Hand(h, false); got != "[ 10♠ ] [  A♥ ] (Blackjack)" {
+		t.Errorf("Hand = %q", got)
+	}
+	soft := game.Hand{}
+	soft.Add(card(deck.Spades, deck.Ace))
+	soft.Add(card(deck.Hearts, deck.Six))
+	if got := r.Hand(soft, false); got != "[  A♠ ] [  6♥ ] (Soft 17)" {
+		t.Errorf("Hand soft = %q", got)
+	}
+	if got := r.Hand(h, true); got != "[ 10♠ ] [ ?? ]" {
+		t.Errorf("Hand hidden = %q", got)
+	}
+}
+
+func TestMoney(t *testing.T) {
+	tests := []struct {
+		n    int
+		want string
+	}{
+		{0, "$0"}, {5, "$5"}, {999, "$999"}, {1000, "$1,000"}, {12345, "$12,345"},
+		{1234567, "$1,234,567"}, {-250, "-$250"}, {-1000, "-$1,000"},
+	}
+	for _, tt := range tests {
+		if got := Money(tt.n); got != tt.want {
+			t.Errorf("Money(%d) = %q, want %q", tt.n, got, tt.want)
+		}
+	}
+	if SignedMoney(15) != "+$15" || SignedMoney(-10) != "-$10" || SignedMoney(0) != "$0" {
+		t.Error("SignedMoney mismatch")
+	}
+}
+
+func scriptedRound(t *testing.T, bet int, ranks ...deck.Rank) *game.Round {
+	t.Helper()
+	cards := make([]deck.Card, len(ranks))
+	for i, rk := range ranks {
+		cards[i] = card(deck.Spades, rk)
+	}
+	rd, err := game.NewRound(deck.NewShoeFromCards(cards), game.DefaultRules(), bet)
+	if err != nil {
+		t.Fatal(err)
+	}
+	return rd
+}
+
+func TestTable(t *testing.T) {
+	r := New(false)
+	rd := scriptedRound(t, 25, deck.Ten, deck.Nine, deck.Seven, deck.King)
+	var buf bytes.Buffer
+	r.Table(&buf, 1000, rd)
+	out := buf.String()
+	for _, want := range []string{"Bankroll: $1,000", "Bet: $25", "Dealer upcard: 9♠", "[ ?? ]", "► Player:", "(Hard 17)", "[$25]"} {
+		if !strings.Contains(out, want) {
+			t.Errorf("table output missing %q:\n%s", want, out)
+		}
+	}
+	if strings.Contains(out, "K♠") {
+		t.Error("hole card should be hidden before dealer plays")
+	}
+
+	// After dealer plays the hole card is revealed.
+	_ = rd.Apply(game.Stand)
+	_ = rd.PlayDealer()
+	buf.Reset()
+	r.Table(&buf, 1000, rd)
+	if !strings.Contains(buf.String(), "K♠") || !strings.Contains(buf.String(), "(Hard 19)") {
+		t.Errorf("hole card should be shown after dealer plays:\n%s", buf.String())
+	}
+}
+
+func TestTableSplitHandsAndColor(t *testing.T) {
+	r := New(true)
+	rd := scriptedRound(t, 10, deck.Eight, deck.Six, deck.Eight, deck.Ten, deck.Two, deck.Three)
+	_ = rd.Apply(game.Split)
+	var buf bytes.Buffer
+	r.Table(&buf, 980, rd)
+	out := buf.String()
+	if !strings.Contains(out, "Hand 1") || !strings.Contains(out, "Hand 2") {
+		t.Errorf("split hands should be labelled:\n%s", out)
+	}
+	if !strings.Contains(out, ansiBold) {
+		t.Error("color mode should emit bold")
+	}
+	if !strings.Contains(out, "Bet: $20") {
+		t.Error("total wagered should reflect both hands")
+	}
+}
+
+func TestResults(t *testing.T) {
+	r := New(true)
+	h := &game.Hand{Bet: 10}
+	results := []game.Result{
+		{Hand: h, Outcome: game.Win, Net: 10},
+		{Hand: h, Outcome: game.Loss, Net: -10},
+		{Hand: h, Outcome: game.Push, Net: 0},
+		{Hand: h, Outcome: game.Blackjack, Net: 15},
+	}
+	var buf bytes.Buffer
+	r.Results(&buf, results)
+	out := buf.String()
+	for _, want := range []string{"Hand 1", "Hand 4", "Win", "+$10", "Loss", "-$10", "Push", "$0", "Blackjack", "+$15", ansiGreen, ansiRed} {
+		if !strings.Contains(out, want) {
+			t.Errorf("results missing %q:\n%s", want, out)
+		}
+	}
+	buf.Reset()
+	New(false).Results(&buf, results[:1])
+	if !strings.HasPrefix(buf.String(), "Result: Win") {
+		t.Errorf("single result label = %q", buf.String())
+	}
+}
+
+func TestPadLeft(t *testing.T) {
+	if padLeft("A♥", 3) != " A♥" {
+		t.Errorf("padLeft = %q", padLeft("A♥", 3))
+	}
+	if padLeft("10♥", 3) != "10♥" {
+		t.Error("padLeft should not pad when already wide enough")
+	}
+}
